 "Traits": [
  {"trait_id":"T_BOUFTOU","nom":"Bouftou","type":"Origine","description":"Votre équipe gagne des résistances Terre et Feu ; les Bouftous en gagnent davantage.","valeur_base":5,"nb_unites_dispo":7,"notes":null},
  {"trait_id":"T_TOFU","nom":"Tofu","type":"Origine","description":"Pour chaque case parcourue, les Tofus gagnent un bonus selon leur classe (voir Bonus_Tofu). Les Tofus Royal cumulent tous les bonus.","valeur_base":null,"nb_unites_dispo":6,"notes":"Bonus volontairement faibles : les attaques des Tofus les font se déplacer souvent."},
  {"trait_id":"T_MOON","nom":"Moon","type":"Origine","description":"Lorsqu'un Moon tombe sous 2/3 puis sous 1/3 de ses PV, il gagne un bouclier proportionnel à ses PV max.","valeur_base":0.3,"nb_unites_dispo":6,"notes":null},
  {"trait_id":"T_COCHON","nom":"Cochon","type":"Origine","description":"Gaz actif 2 s toutes les 5 s : pendant ce temps, les sorts des Cochons gagnent leur effet « Gaz actif ».","valeur_base":null,"nb_unites_dispo":6,"notes":"Préciser : quelles stats, durée/zone du gaz ?"},
  {"trait_id":"T_DOPEUL","nom":"Dopeul","type":"Origine","description":"Les Dopeuls gagnent des PV et de la vitesse d'attaque pour chaque Dopeul unique sur le plateau. De plus, leurs compétences se déclenchent une seconde fois avec une efficacité réduite.","valeur_base":null,"nb_unites_dispo":8,"notes":null},
  {"trait_id":"T_IOP","nom":"Iop","type":"Classe","description":"Au début de chaque combat, les Iops gagnent de la force de façon permanente (cumul sur la run).","valeur_base":3,"nb_unites_dispo":6,"notes":"valeur_base = 3, mais Paliers indique +2 force : laquelle garder ?"},
  {"trait_id":"T_CRA","nom":"Cra","type":"Classe","description":"Les Cras gagnent +1 PO et de l'agilité.","valeur_base":null,"nb_unites_dispo":8,"notes":"+15 agilité = maintenant +0,15 attaque/s (plus du critique). Passer en chance si le but était le critique ?"},
  {"trait_id":"T_ENI","nom":"Eniripsa","type":"Classe","description":"Toutes les 4 s : vague de soin (% PV max) sur l'équipe et bonus de recharge PA pendant 2 s.","valeur_base":0.15,"nb_unites_dispo":8,"notes":"Palier 4 : 15 % × 1,5 = 22,5 % (pas un nombre entier). Passer le multiplicateur à 2 (30 %) ou la base à 16 % (24 %) ?"},
  {"trait_id":"T_HUPPER","nom":"Huppermage","type":"Classe","description":"L'équipe gagne de l'intelligence, les Huppermages le double.","valeur_base":30,"nb_unites_dispo":8,"notes":null},
  {"trait_id":"T_ZOBAL","nom":"Zobal","type":"Classe","description":"Bouclier (% PV) sur l'allié qui a le plus de PV ; à sa mort, le bouclier rebondit sur l'allié vivant avec le plus de PV.","valeur_base":null,"nb_unites_dispo":7,"notes":null},
  {"trait_id":"T_ROYAL","nom":"Royal","type":"Classe","description":"À chaque sort, invoque une unité de même origine dont le coût = nombre d'unités de cette origine sur le terrain. Le palier fixe l'étoile de l'invocation (1★ / 2★ / 3★).","valeur_base":null,"nb_unites_dispo":5,"notes":"Si aucune unité de l'origine n'existe à ce coût : prendre le coût inférieur le plus proche. Une seule invocation active par Royal ? (à confirmer)"},
  {"trait_id":"T_FORET","nom":"Foret","type":"Origine","description":"À chaque fin de combat : +XP pour le joueur et +2 chance permanente (= +2 % de critique) pour les unités Forêt.","valeur_base":null,"nb_unites_dispo":5,"notes":"Combat ou round ? (ici : 1 round = 1 combat). XP = XP du joueur ?"},
  {"trait_id":"T_OSAMODAS","nom":"Osamodas","type":"Classe","description":"Au début de chaque combat, bénit des alliés tirés au hasard : +20 % rés. Terre et Feu, +30 force, +30 intelligence, +30 agilité, et chaque attaque de base soigne l'attaquant de 20 PV.","valeur_base":null,"nb_unites_dispo":6,"notes":null},
  {"trait_id":"T_DRAGOEUF","nom":"Dragoeuf","type":"Origine","description":"Les dégâts des unités Dragoeuf infligent Brûlure et Hémorragie pendant 3 s. Leurs brûlures se cumulent avec celles d'autres sources.","valeur_base":null,"nb_unites_dispo":8,"notes":null},
  {"trait_id":"T_STEAMER","nom":"Steamer","type":"Classe","description":"À partir de 3 Steamer : une case spéciale apparaît au milieu du camp du joueur pendant la préparation. La classe 1 de l'unité posée dessus détermine la tourelle (voir Bonus_Steamer), invoquée sur une case adjacente au début du combat. L'unité et la tourelle peuvent être déplacées. Stats de la tourelle = somme des stats des Steamer présents × 0,8.","valeur_base":0.8,"nb_unites_dispo":6,"notes":"La tourelle n'attaque pas : +1 PA à chaque sort de Steamer, effet lancé à 3 PA (Parametres)."},
  {"trait_id":"T_SACRIEUR","nom":"Sacrieur","type":"Classe","description":"Les Sacrieurs gagnent de la force et du vol de vie.","valeur_base":20,"nb_unites_dispo":6,"notes":null},
  {"trait_id":"T_BETES","nom":"Bêtes de la nuit","type":"Origine","description":"Assassins : commencent le combat invisibles pendant 1 s, foncent vers l'ennemi le plus éloigné et gagnent de la chance (critique).","valeur_base":25,"nb_unites_dispo":4,"notes":null},
  {"trait_id":"T_EMBRUNS","nom":"Seigneur des Embruns","type":"Origine","description":"Le Seigneur des Embruns profite des effets de tous les traits actifs de son équipe, sans compter dans leurs paliers. Exception : Royal (pas d'invocation). Dopeul : il reçoit les bonus de stats et ses DÉGÂTS se déclenchent deux fois, mais pas ses bonus de stats.","valeur_base":null,"nb_unites_dispo":1,"notes":null},
  {"trait_id":"T_ECAFLIP","nom":"Ecaflip","type":"Classe","description":"Au début de chaque combat, un trait ACTIF de l'équipe tiré au hasard gagne un palier complet. Si le trait tiré est déjà à son palier max, nouveau tirage.","valeur_base":null,"nb_unites_dispo":1,"notes":null}
 ],
